<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VF-Exportjournal</title><link rel="stylesheet" href="app.css"></head><body><div class="card"><a class="button secondary" href="vf_day_export.php">Tagesexport</a><a class="button secondary" href="dashboard.php">Dashboard</a></div><h1>VF-Exportjournal</h1><div class="card"><label>Von <input id="from" type="date" value="<?=$today?>"></label><label>Bis <input id="to" type="date" value="<?=$today?>"></label><select id="status"><option value="all">Alle Status</option><option>success</option><option>failed</option><option>pending</option><option value="reconciliation_required">Abstimmung erforderlich</option></select><button id="load">Journal laden</button><button id="runs">Läufe laden</button></div><div id="out" class="card">Noch nicht geladen.</div><script>'use strict';const csrf=<?=json_encode(csrf_token())?>,o=document.getElementById('out'),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function api(action){const r=await fetch('api_vf_export_journal.php',{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,from:from.value,to:to.value,status:status.value,csrf_token:csrf})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Fehler');return d}load.onclick=async()=>{try{const d=await api('list');o.innerHTML=`<table><tr><th>ID</th><th>LSZJ</th><th>VF</th><th>Flug</th><th>Status</th><th>Zeit</th><th>Hinweis</th></tr>${d.items.map(i=>`<tr><td>${i.id}</td><td>${i.accounting_entry_id}<br>Op ${i.operation_id}</td><td>${e(i.vf_flid)}</td><td>${e(i.callsign)}<br>${e(i.pilot_name)}<br>${e(i.departure_time)}</td><td>${e(i.status)}</td><td>${e(i.attempted_at)}<br>${e(i.succeeded_at)}</td><td>${e(i.error_message||i.reconciliation_note)}</td></tr>`).join('')}</table>`}catch(x){o.textContent=x.message}};runs.onclick=async()=>{try{const d=await api('runs');o.innerHTML=`<table><tr><th>Lauf</th><th>Datum</th><th>Status</th><th>Angefordert</th><th>Erfolg</th><th>Fehler</th><th>Abstimmung</th><th>Start</th><th>Ende</th></tr>${d.items.map(i=>`<tr><td>${i.id}</td><td>${e(i.flight_date)}</td><td>${e(i.status)}</td><td>${i.requested_count}</td><td>${i.successful_count}</td><td>${i.failed_count}</td><td>${i.reconciliation_count}</td><td>${e(i.started_at)}</td><td>${e(i.completed_at)}</td></tr>`).join('')}</table>`}catch(x){o.textContent=x.message}};</script></body></html>
